package local.zfttests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;
public class Article extends Instrumentation {
 private Activity a;private Class<?> c;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void require(boolean x,String m){if(!x)throw new AssertionError(m);}
 private Object field(String n)throws Exception{Field f=c.getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 private String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
 private void noQuoteLines(View v){if(v instanceof TextView){CharSequence t=((TextView)v).getText();if(t instanceof android.text.Spanned)require(((android.text.Spanned)t).getSpans(0,t.length(),android.text.style.QuoteSpan.class).length==0,"no quote border");}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)noQuoteLines(((ViewGroup)v).getChildAt(i));}
 private void screenshot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 private boolean web(View v){if(v instanceof android.webkit.WebView)return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(web(((ViewGroup)v).getChildAt(i)))return true;return false;}
 public void onStart(){Bundle out=new Bundle();try{c=getTargetContext().getClassLoader().loadClass("local.zft.AiActivity");a=startActivitySync(new Intent().setClassName(getTargetContext(),c.getName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->{try{Method open=c.getDeclaredMethod("openArticle",JSONObject.class);open.setAccessible(true);open.invoke(a,new JSONObject("{\"id\":\"qhvh1rm03vym5ns6ku6hjkkmq\",\"title\":\"SpaceX 财报要点\",\"links\":{\"aihot\":\"https://aihot.news/items/qhvh1rm03vym5ns6ku6hjkkmq\"}}"));}catch(Exception e){throw new RuntimeException(e);}});
 long end=System.currentTimeMillis()+45000;boolean[] ready={false};while(System.currentTimeMillis()<end){runOnMainSync(()->{try{View reader=(View)field("reader");ready[0]=reader.findViewWithTag("ai.image.loaded")!=null&&text(reader).contains("路易斯安那");}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])break;Thread.sleep(300);}require(ready[0],"full translated body including final paragraph and actual image loaded");
 Thread.sleep(300);screenshot("ai-reading-layout.png");runOnMainSync(()->{try{View reader=(View)field("reader");require(!web(reader),"no embedded website");noQuoteLines(reader);require(!text(reader).contains("观看直播")&&!text(reader).contains("引用 · SpaceX"),"no appended livestream quote");require(!text(reader).contains("查看原文")&&!text(reader).contains("推荐理由"),"no unwanted external link or duplicated recommendation");ImageView image=reader.findViewWithTag("ai.image.loaded");require(image.getDrawable().getIntrinsicWidth()>100,"real news image decoded");image.requestRectangleOnScreen(new android.graphics.Rect(0,0,image.getWidth(),image.getHeight()),true);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(800);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"ai-full-image-preview.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();runOnMainSync(()->{try{require(field("reader")==null&&!a.isFinishing(),"back returns to feed");}catch(Exception e){throw new RuntimeException(e);}});
 Class<?> article=getTargetContext().getClassLoader().loadClass("local.zft.AiArticle");Method imageUrl=article.getDeclaredMethod("imageUrl",String.class);imageUrl.setAccessible(true);boolean blocked=false;try{imageUrl.invoke(null,"file:///sdcard/private");}catch(InvocationTargetException expected){blocked=true;}require(blocked,"unsafe image URL rejected");out.putString("result","PASS complete translated article, final paragraph, actual native image, no quote borders/appended livestream/WebView/external links/reasons, system back, image URL guard");finish(-1,out);
 }catch(Throwable e){out.putString("result","FAIL "+e);finish(0,out);}}
}
